/** Shared lifecycle rules. Transcript content remains owned by the caller. */
export type ExecutionStatus = 'inProgress' | 'completed' | 'failed' | 'interrupted';
export interface ExecutionTurn { id: string; status: string }

export function isTerminalTurn(turn: ExecutionTurn | undefined): boolean {
  return Boolean(turn && ['completed', 'failed', 'interrupted'].includes(turn.status));
}

export class TurnExecutionTracker {
  private readonly threads = new Map<string, ExecutionTurn[]>();

  status(threadId: string, turnId: string): string | undefined {
    return this.threads.get(threadId)?.find(turn => turn.id === turnId)?.status;
  }

  terminal(threadId: string, turnId: string): boolean {
    const status = this.status(threadId, turnId);
    return status !== undefined && status !== 'inProgress';
  }

  current(threadId: string): string | undefined {
    const latest = this.threads.get(threadId)?.at(-1);
    return latest?.status === 'inProgress' ? latest.id : undefined;
  }

  /** False means a stale start; callers must not run start side effects. */
  observe(threadId: string, turn: ExecutionTurn, transcript: readonly ExecutionTurn[] = []): boolean {
    if (!turn.id || !['inProgress', 'completed', 'failed', 'interrupted'].includes(turn.status)) return false;
    const transcriptIndex = transcript.findIndex(item => item.id === turn.id);
    if (turn.status === 'inProgress' && transcriptIndex >= 0
      && (isTerminalTurn(transcript[transcriptIndex]) || transcriptIndex < transcript.length - 1)) return false;
    const turns = this.threads.get(threadId) ?? [];
    const index = turns.findIndex(item => item.id === turn.id);
    if (turn.status === 'inProgress' && (isTerminalTurn(turns[index]) || (index >= 0 && index < turns.length - 1))) return false;
    if (index >= 0) turns[index] = { id: turn.id, status: turn.status };
    else if (isTerminalTurn(turn) && turns.at(-1)?.status === 'inProgress') {
      // A completion for an unknown predecessor cannot end a known new turn.
      turns.splice(turns.length - 1, 0, { id: turn.id, status: turn.status });
    } else turns.push({ id: turn.id, status: turn.status });
    // Bound retained history; full transcripts still protect older loaded turns.
    if (turns.length > 256) turns.splice(0, turns.length - 256);
    this.threads.delete(threadId);
    this.threads.set(threadId, turns);
    if (this.threads.size > 512) {
      const idle = [...this.threads.keys()].find(id => !this.current(id));
      if (idle) this.threads.delete(idle);
    }
    return true;
  }

  snapshot(threadId: string, turns: readonly ExecutionTurn[]): void {
    turns = turns.filter(turn => turn.id && ['inProgress', 'completed', 'failed', 'interrupted'].includes(turn.status));
    if (!turns.length) return;
    // Seed known order before observing statuses; a snapshot can contain both
    // a completed predecessor and its running successor.
    const previous = this.threads.get(threadId) ?? [];
    const incoming = turns.map(turn => {
      const known = previous.find(item => item.id === turn.id);
      return { id: turn.id, status: isTerminalTurn(known) && turn.status === 'inProgress' ? known!.status : turn.status };
    });
    const lastKnownIndex = previous.findIndex(turn => turn.id === incoming.at(-1)?.id);
    const newer = lastKnownIndex >= 0 ? previous.slice(lastKnownIndex + 1) : [];
    this.threads.set(threadId, [...incoming, ...newer].slice(-256));
    if (this.threads.size > 512) {
      const idle = [...this.threads.keys()].find(id => id !== threadId && !this.current(id));
      if (idle) this.threads.delete(idle);
    }
  }

  recentThreads(): string[] { return [...this.threads.keys()].reverse(); }
  activeTurns(): ReadonlyMap<string, string> {
    return new Map([...this.threads.keys()].flatMap(id => {
      const turn = this.current(id);
      return turn ? [[id, turn] as const] : [];
    }));
  }
  turns(threadId: string): ExecutionTurn[] { return (this.threads.get(threadId) ?? []).map(turn => ({ ...turn })); }
  forget(threadId: string): void { this.threads.delete(threadId); }
  clear(): void { this.threads.clear(); }
}
